&qdec0 {
	status = "okay";
};

&qspi {
	status = "okay";
	pinctrl-0 = <&qspi_default>;
	pinctrl-1 = <&qspi_sleep>;
	pinctrl-names = "default", "sleep";
};

&rng {
	status = "okay";
};

&rtc0 {
	status = "okay";
};

&rtc1 {
	status = "okay";
};

&rtc2 {
	status = "okay";
};

&timer0 {
	status = "okay";
};

&timer1 {
	status = "okay";
};

&timer2 {
	status = "okay";
};

&timer3 {
	status = "okay";
};

&timer4 {
	status = "okay";
};

&twis0 {
	status = "okay";
	pinctrl-0 = <&twis0_default>;
	pinctrl-1 = <&twis0_sleep>;
	pinctrl-names = "default", "sleep";
};

&twis1 {
	status = "okay";
	pinctrl-0 = <&twis1_default>;
	pinctrl-1 = <&twis1_sleep>;
	pinctrl-names = "default", "sleep";
};

&uart1 {
	status = "okay";
	pinctrl-0 = <&uart1_default>;
	pinctrl-1 = <&uart1_sleep>;
	pinctrl-names = "default", "sleep";
};

&wdt0 {
